SINA_SMART["anat1-hand-vessels-nerves"] = {"lecture":"anat1-hand-vessels-nerves","title":"Vascularisation and innervation of the hand","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-hand-vessels-nerves:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"insufficient-source"},{"id":"anat1-hand-vessels-nerves:e0","text":"Radial pulse groove: between brachioradialis and FCR tendons.","topic":"Arteries and palmar arches","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-hand-vessels-nerves:e1","text":"Radial artery → snuffbox → 1st web space → deep arch.","topic":"Arteries and palmar arches","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-hand-vessels-nerves:e3","text":"Superficial arch: ulnar a. + radiopalmar branch (in front of tendons).","topic":"Arteries and palmar arches","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-hand-vessels-nerves:e4","text":"Deep arch: radial a. + ulnopalmar branch (behind tendons).","topic":"Arteries and palmar arches","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-hand-vessels-nerves:e2","text":"Ulnar artery lateral to pisiform, with the ulnar nerve.","topic":"Nerves","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-hand-vessels-nerves:e5","text":"Carpal tunnel: carpal bones + flexor retinaculum; median nerve + flexor tendons.","topic":"Nerves","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-hand-vessels-nerves:e6","text":"Median sensory: thumb, index, middle, lateral half of ring.","topic":"Nerves","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-hand-vessels-nerves:e7","text":"Ulnar (Guyon's canal): interossei, adductor pollicis, hypothenar; sensory medial half ring + little finger.","topic":"Nerves","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1jsfxsb":"a","1d0rfr5":"a","7w09iz":"a","1kjk10i":"a","rvgqcp":"a","1l1xtdb":"a","re4p3c":"a","qsg08k":"a","ju02j7":"a","1qg5326":"a"},"mapCounts":{"verified":0,"auto":10,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-hand-vessels-nerves:s0":{"s":0,"u":["The hand is supplied by the radial and ulnar arteries , joined by two palmar arches , and innervated in the palm by the median and ulnar nerves , which pass through the carpal tunnel and Guyon's canal ."],"dp":[]},"anat1-hand-vessels-nerves:e0":{"s":1,"u":["Radial pulse groove: between brachioradialis and FCR tendons.","Radial artery : at the wrist runs in the pulse groove between the brachioradialis (lateral) and flexor carpi radialis (medial) tendons, gives the radiopalmar (superficial palmar) branch , passes through the floor of the anatomical snuffbox to the back of the hand, then returns to the palm through the first web space .","Deep palmar arch : radial artery + ulnopalmar branch , behind the flexor tendons."],"dp":[]},"anat1-hand-vessels-nerves:e1":{"s":1,"u":["Radial artery → snuffbox → 1st web space → deep arch.","Deep palmar arch : radial artery + ulnopalmar branch , behind the flexor tendons.","Radial artery : at the wrist runs in the pulse groove between the brachioradialis (lateral) and flexor carpi radialis (medial) tendons, gives the radiopalmar (superficial palmar) branch , passes through the floor of the anatomical snuffbox to the back of the hand, then returns to the palm through the first web space ."],"dp":[{"h":"Note","t":"Radial artery path: pulse groove → floor of the anatomical snuffbox → first web space (between the heads of the first dorsal interosseous) → deep arch."}]},"anat1-hand-vessels-nerves:e3":{"s":1,"u":["Superficial arch: ulnar a. + radiopalmar branch (in front of tendons).","Superficial palmar arch : ulnar artery + radiopalmar branch , in front of the flexor tendons, with the branches of the median nerve.","Deep palmar arch : radial artery + ulnopalmar branch , behind the flexor tendons."],"dp":[{"h":"Note","t":"Superficial palmar arch = mainly ulnar artery (in front of the tendons, level with the extended thumb). Deep arch = mainly radial artery (behind the tendons, more proximal)."}]},"anat1-hand-vessels-nerves:e4":{"s":1,"u":["Deep arch: radial a. + ulnopalmar branch (behind tendons).","Deep palmar arch : radial artery + ulnopalmar branch , behind the flexor tendons.","Ulnar artery : medially, lateral to the pisiform , stays anterior and gives the ulnopalmar (deep palmar) branch ."],"dp":[]},"anat1-hand-vessels-nerves:e2":{"s":2,"u":["Ulnar artery lateral to pisiform, with the ulnar nerve.","Ulnar nerve : medial, lateral to the pisiform, with the ulnar artery, through Guyon's canal ."],"dp":[{"h":"Clinical","t":"Allen's test checks that the ulnar artery alone can supply the hand before radial artery cannulation or harvest."}]},"anat1-hand-vessels-nerves:e5":{"s":2,"u":["Carpal tunnel: carpal bones + flexor retinaculum; median nerve + flexor tendons.","Median nerve : passes through the carpal tunnel (carpal bones behind, flexor retinaculum in front) with the finger flexor tendons; gives the thenar branch (abductor pollicis brevis, opponens pollicis, superficial head of flexor pollicis brevis) and interdigital nerves to the 1st-3rd spaces."],"dp":[{"h":"Why carpal tunnel syndrome spares the little finger","t":"The carpal tunnel is a rigid channel shared by nine flexor tendons and the median nerve. Swelling of the tendons or wrist compresses the nerve, causing tingling in the thumb, index, middle and half the ring finger, the median territory. The ulnar nerve takes a separate route through Guyon's canal, so the little finger stays normal, a key clue in diagnosis. Source: the lecture's carpal tunnel and nerve territory sections."},{"h":"Note","t":"Carpal tunnel = carpal bones + flexor retinaculum; contains the median nerve and 9 flexor tendons (FDS ×4, FDP ×4, FPL). Guyon's canal = ulnar nerve and artery, beside the pisiform."}]},"anat1-hand-vessels-nerves:e6":{"s":2,"u":["Median sensory: thumb, index, middle, lateral half of ring.","Sensory: palmar surface and pulp of the thumb, index, middle and lateral half of the ring finger .","Sensory: medial half of the ring finger and the whole little finger (palmar side)."],"dp":[{"h":"Clinical","t":"Carpal tunnel syndrome : tingling in thumb, index, middle and half the ring finger, worse at night; thenar wasting. The palm is spared because the palmar cutaneous branch passes over the retinaculum."},{"h":"Note","t":"Sensory map : median = palmar thumb, index, middle, lateral half of ring; ulnar = medial half of ring + little finger; radial = dorsum of the first web space."}]},"anat1-hand-vessels-nerves:e7":{"s":2,"u":["Ulnar (Guyon's canal): interossei, adductor pollicis, hypothenar; sensory medial half ring + little finger.","Sensory: medial half of the ring finger and the whole little finger (palmar side).","Deep branch : all interossei , adductor pollicis and the hypothenar muscles ."],"dp":[]}},"meta":{"1jsfxsb":{"a":"relationship","vg":"anat1-hand-vessels-nerves:e0/relationship/1"},"1d0rfr5":{"a":"recall","vg":"anat1-hand-vessels-nerves:e1/recall/1"},"7w09iz":{"a":"recall","vg":"anat1-hand-vessels-nerves:e3/recall/1"},"1kjk10i":{"a":"recall","vg":"anat1-hand-vessels-nerves:e4/recall/1"},"rvgqcp":{"a":"recall","vg":"anat1-hand-vessels-nerves:e5/recall/1"},"1l1xtdb":{"a":"recall","vg":"anat1-hand-vessels-nerves:e5/recall/2"},"re4p3c":{"a":"recall","vg":"anat1-hand-vessels-nerves:e6/recall/1"},"qsg08k":{"a":"recall","vg":"anat1-hand-vessels-nerves:e2/recall/1"},"ju02j7":{"a":"recall","vg":"anat1-hand-vessels-nerves:e7/recall/1"},"1qg5326":{"a":"recall","vg":"anat1-hand-vessels-nerves:e7/recall/2"}},"explRev":"cba63940d418"};
